            //
            aIngress = (RotL64(aFireLaneC[((aIndex + 7137U)) & S_BLOCK1], 51U) ^ RotL64(aEarthLaneC[((aIndex + 7486U)) & S_BLOCK1], 34U));
            aIngress ^= RotL64(aFireLaneA[((aIndex + 8599U)) & S_BLOCK1], 5U);
