    std::uint64_t *aTwistOrbiterUpdateSaltD = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltD;
    std::uint64_t *aTwistOrbiterUpdateSaltE = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltE;
