            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x426B5DC9B94B5594ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x9E27F61CCCE3143FULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 183U)) & S_SALT1];
