            aOrbiterF = (aWandererJ + RotL64(aScatter, 27U)) + 0x26A22DBBB0FA7865ULL;
            aOrbiterJ = (aWandererF + RotL64(aPrevious, 39U)) + 0xDAEB5AE190AFAC06ULL;
            aOrbiterI = ((aWandererA + RotL64(aScatter, 35U)) + RotL64(aCarry, 27U)) + 0x3299D4D9B71829A0ULL;
            aOrbiterE = (aWandererB + RotL64(aCross, 13U)) + 0x37BD0C17282C0A4AULL;
            aOrbiterC = (aWandererG + RotL64(aIngress, 58U)) + 0xB1EA4DA44CB64270ULL;
            aOrbiterH = ((aWandererK + RotL64(aCross, 21U)) + 0x4239DDE9B39B359FULL) + aKeyRotateBOrbiterAssignSaltC[((aIndex + 249U)) & S_SALT1];
