            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xBB75896A0B4178B8ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0xC28F48D6F10D96A7ULL) ^ aKeyRotateBOrbiterUpdateSaltB[((aIndex + 86U)) & S_SALT1];
