            aWandererB = aWandererB + (((RotL64(aPrevious, 43U) + RotL64(aOrbiterF, 51U)) + aOrbiterJ) + RotL64(aCarry, 41U));
            aWandererI = aWandererI ^ ((RotL64(aCross, 51U) + aOrbiterF) + RotL64(aOrbiterA, 11U));
            aWandererC = aWandererC + (((RotL64(aIngress, 37U) + aOrbiterG) + RotL64(aOrbiterB, 28U)) + RotL64(aCarry, 5U));
            aWandererD = aWandererD ^ (((RotL64(aCross, 56U) + RotL64(aOrbiterE, 43U)) + aOrbiterA) + aKeyRotateBWandererUpdateSaltF[((aIndex + 184U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererD, 47U) ^ aWandererC);
