            aOrbiterA = ((aOrbiterA ^ aOrbiterJ) ^ 0xEE525AC3DE5F746CULL) ^ aKeyRotateBOrbiterUpdateSaltB[(((255U - aIndex) + 223U)) & S_SALT1];
