            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterD = ((aWandererB + RotL64(aScatter, 27U)) + RotL64(aCarry, 47U)) + 0xE6449625171229F3ULL;
            aOrbiterC = (aWandererI + RotL64(aIngress, 30U)) + 0xE40C4595DE77352BULL;
            aOrbiterF = (aWandererH + RotL64(aCross, 23U)) + 0x9CE4CBF97D80DCD2ULL;
            aOrbiterG = (aWandererE + RotL64(aPrevious, 35U)) + 0x72BC4626A3094094ULL;
            aOrbiterH = ((aWandererF + RotL64(aCross, 39U)) + 0x9B90F914478891C1ULL) + aKeyRotateBOrbiterAssignSaltC[((aIndex + 191U)) & S_SALT1];
